package com.chk.agentbrowser;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.os.*;
import android.text.*;
import android.text.style.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

/** Read-only first. Selection and copy are always available; edits are explicit and hash guarded. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class FileViewerActivity extends Activity {
    private static final int INK=0xff202124,BLUE=0xff146cce;
    private String path,kind="",format="",raw="",original="",sha="";private JSONObject detected,result;
    private LinearLayout root,body,toolbar,pages;private TextView status,text;private EditText editor;private ScrollView scroll;
    private boolean alive,loaded,editing;private int offset,page=1,generation;private long byteOffset;private boolean hexMode;private String table="";private final ArrayDeque<Integer> previous=new ArrayDeque<>();
    private androidx.media3.exoplayer.ExoPlayer player;private Bitmap bitmap;
    @Override public void onCreate(Bundle state){super.onCreate(state);alive=true;path=getIntent().getStringExtra("path");root=MobileUi.column(this);root.setBackgroundColor(0xfffafbff);setContentView(root);
        TextView back=label("‹ "+(path==null?"Fichier":new File(path).getName()),19);back.setTypeface(null,Typeface.BOLD);root.addView(back);back.setOnClickListener(v->onBackPressed());
        HorizontalScrollView tools=new HorizontalScrollView(this);toolbar=new LinearLayout(this);tools.addView(toolbar);root.addView(tools);button(toolbar,"Copier tout",()->copyAll());button(toolbar,"Rechercher",()->search());button(toolbar,"Modifier",()->edit());button(toolbar,"⋮",()->menu());
        status=label("Ouverture locale…",12);root.addView(status);scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=MobileUi.column(this);scroll.addView(body);
        pages=new LinearLayout(this);root.addView(pages);button(pages,"‹ Précédent",()->previous());button(pages,"Suivant ›",()->next());load();
    }
    private TextView label(String value,int size){TextView v=MobileUi.text(this,value,size,INK);v.setTextIsSelectable(true);return v;}
    private void button(LinearLayout bar,String title,Runnable action){TextView button=label(title,14);button.setTextColor(BLUE);button.setMinHeight(MobileUi.dp(this,48));button.setGravity(Gravity.CENTER_VERTICAL);button.setContentDescription(title);button.setTag(title);bar.addView(button);button.setOnClickListener(v->action.run());}
    private void load(){int ticket=++generation;loaded=false;WorkspaceCommands.IO.execute(()->{
        try{JSONObject info=FileFormats.detect(this,path);JSONObject args=new JSONObject().put("offset",offset).put("page",page).put("page_count",1).put("byte_offset",byteOffset).put("table",table);JSONObject value=hexMode?FileContent.hex(this,path,byteOffset).put("detected",info):UniversalFiles.preview(this,path,args);Bitmap picture=null;
            if(!hexMode&&info.getString("format").equals("pdf"))picture=pdfImage(new WorkspaceStore(this).file(path),page-1);
            else if(!hexMode&&info.getString("kind").equals("image"))picture=image(new WorkspaceStore(this).file(path));
            Bitmap ready=picture;runOnUiThread(()->{if(!alive||ticket!=generation){if(ready!=null)ready.recycle();return;}detected=info;result=value;kind=info.optString("kind");format=info.optString("format");draw(ready);loaded=true;acknowledge();});
        }catch(Exception ex){runOnUiThread(()->{if(!alive||ticket!=generation)return;status.setText("Ouverture limitée : "+message(ex));body.removeAllViews();text=label("Le lecteur intégré ne peut pas décoder ce contenu. Le fichier reste disponible via Informations, Aperçu hexadécimal ou Ouvrir avec…",16);body.addView(text);loaded=true;acknowledge();});}
    });}
    private void draw(Bitmap picture){stopPlayer();if(bitmap!=null)bitmap.recycle();bitmap=picture;body.removeAllViews();editor=null;editing=false;
        status.setText(format.toUpperCase(Locale.ROOT)+" · "+detected.optLong("size_bytes")+" octets · Lecture seule"+(detected.optString("warning").isEmpty()?"":"\n"+detected.optString("warning"))+(result.has("table_warning")?"\n"+result.optString("table_warning"):"")+(result.has("json_valid")?"\nJSON : "+(result.optBoolean("json_valid")?"valide":result.optString("validation_error")):""));
        raw=result.optString("text",result.toString());
        if(picture!=null){ImageView image=new ImageView(this);image.setImageBitmap(picture);image.setAdjustViewBounds(true);image.setContentDescription("Aperçu du fichier");body.addView(image,new LinearLayout.LayoutParams(-1,MobileUi.dp(this,360)));ScaleGestureDetector zoom=new ScaleGestureDetector(this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){float factor=Math.max(1,Math.min(5,image.getScaleX()*d.getScaleFactor()));image.setScaleX(factor);image.setScaleY(factor);return true;}});image.setOnTouchListener((v,e)->{zoom.onTouchEvent(e);if(e.getAction()==MotionEvent.ACTION_UP)v.performClick();return true;});}
        if(kind.equals("media")||kind.equals("audio")){
            player=new androidx.media3.exoplayer.ExoPlayer.Builder(this).build();androidx.media3.ui.PlayerView view=new androidx.media3.ui.PlayerView(this);view.setPlayer(player);body.addView(view,new LinearLayout.LayoutParams(-1,MobileUi.dp(this,260)));
            try{player.setMediaItem(new androidx.media3.common.MediaItem.Builder().setUri(new WorkspaceStore(this).uri(path)).setMimeType(detected.getString("mime_type")).build());player.addListener(new androidx.media3.common.Player.Listener(){@Override public void onPlayerError(androidx.media3.common.PlaybackException error){status.setText("Codec absent ou média corrompu : "+error.getErrorCodeName()+" · Ouvrir avec… reste disponible");}});player.prepare();}catch(Exception ex){status.setText(message(ex));}
        }
        if(result.optJSONArray("entries")!=null){JSONArray entries=result.optJSONArray("entries");for(int i=0;i<entries.length();i++){JSONObject entry=entries.optJSONObject(i);if(entry==null)continue;TextView row=label((entry.optBoolean("directory")?"▱ ":"▤ ")+entry.optString("name"),14);body.addView(row);row.setOnClickListener(v->archiveEntry(entry.optString("name")));}button(body,"Extraire le ZIP dans un nouveau dossier",()->extract());}
        if(result.optJSONArray("tables")!=null){button(body,"Choisir une table",()->chooseTable());}
        if(result.optJSONArray("rows")!=null)drawTable(result.optJSONArray("columns"),result.optJSONArray("rows"));
        text=label(raw,15);text.setTag("file_content");text.setTextIsSelectable(true);if(kind.equals("text")&&!Arrays.asList("txt","md","markdown","csv","tsv").contains(format))text.setTypeface(Typeface.MONOSPACE);if(format.equals("md")||format.equals("markdown"))text.setText(markdown(raw));body.addView(text);scroll.scrollTo(0,0);
    }
    private CharSequence markdown(String value){SpannableString styled=new SpannableString(value);int at=0;for(String line:value.split("\n",-1)){if(line.startsWith("#")){styled.setSpan(new StyleSpan(Typeface.BOLD),at,at+line.length(),0);styled.setSpan(new ForegroundColorSpan(BLUE),at,at+line.length(),0);}at+=line.length()+1;}return styled;}
    private void drawTable(JSONArray columns,JSONArray rows){HorizontalScrollView horizontal=new HorizontalScrollView(this);TableLayout table=new TableLayout(this);horizontal.addView(table);body.addView(horizontal);if(columns!=null)addRow(table,columns,true);for(int i=0;i<Math.min(100,rows.length());i++)addRow(table,rows.optJSONArray(i),false);if(rows.length()>100)body.addView(label("Aperçu des 100 premières lignes de cette page",12));}
    private void addRow(TableLayout table,JSONArray values,boolean header){if(values==null)return;TableRow row=new TableRow(this);for(int i=0;i<Math.min(100,values.length());i++){TextView cell=label(values.optString(i),13);cell.setMaxWidth(MobileUi.dp(this,280));if(header)cell.setTypeface(null,Typeface.BOLD);row.addView(cell);}table.addView(row);}
    private void chooseTable(){JSONArray tables=result.optJSONArray("tables");if(tables==null)return;String[] names=new String[tables.length()];for(int i=0;i<names.length;i++)names[i]=tables.optString(i);new AgentDialog.Builder(this).setTitle("Tables SQLite · lecture seule").setItems(names,(d,n)->{WorkspaceCommands.IO.execute(()->{try{JSONObject value=UniversalFiles.database(this,path,new JSONObject().put("table",names[n]));runOnUiThread(()->{if(alive){table=names[n];offset=0;result=value;draw(null);}});}catch(Exception ex){error(ex);}});}).show();}
    private void archiveEntry(String name){WorkspaceCommands.IO.execute(()->{try{JSONObject entry=UniversalFiles.archiveText(this,path,name);runOnUiThread(()->{if(!alive)return;TextView content=label(entry.optString("text"),14);content.setTextIsSelectable(true);ScrollView box=new ScrollView(this);box.addView(content);new AgentDialog.Builder(this).setTitle(name).setView(box).setPositiveButton("Copier",(d,n)->copy(entry.optString("text"))).setNegativeButton("Fermer",null).show();});}catch(Exception ex){error(ex);}});}
    private void next(){if(editing){toast("Termine l’édition avant de changer de page");return;}if(result==null)return;if(format.equals("pdf")||result.has("total_pages")){if(page>=result.optInt("page_count",result.optInt("total_pages",page)))return;page++;offset=0;load();return;}if(result.has("next_byte_offset")){long next=result.optLong("next_byte_offset",-1);if(next>=0){byteOffset=next;load();}return;}int next=result.optInt("next_offset",-1);if(next>=0){previous.addLast(offset);offset=next;load();}}
    private void previous(){if(editing)return;if(result!=null&&result.has("next_byte_offset")){byteOffset=Math.max(0,byteOffset-512);load();return;}if(format.equals("pdf")||result!=null&&result.has("total_pages")){if(page>1){page--;offset=0;load();}}else if(!previous.isEmpty()){offset=previous.removeLast();load();}}
    private void copyAll(){if(editing&&editor!=null){copy(editor.getText().toString());return;}if(hexMode||!kind.equals("text")){copy(raw);return;}WorkspaceCommands.IO.execute(()->{try{String full=FileContent.full(this,path,200000);runOnUiThread(()->{if(alive)copy(full);});}catch(Exception ex){error(ex);}});}
    private void copy(String value){if(value.length()>200000){toast("Texte trop long pour le presse-papiers : sélectionne un passage ou partage le fichier");return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(new File(path).getName(),value));toast("Texte copié intégralement");}
    private void search(){EditText query=new EditText(this);query.setSingleLine();new AgentDialog.Builder(this).setTitle("Rechercher dans le fichier").setView(query).setPositiveButton("Rechercher",(d,n)->{String needle=query.getText().toString();if(needle.isEmpty())return;WorkspaceCommands.IO.execute(()->{try{if(kind.equals("text")){try(Reader reader=FileContent.reader(new WorkspaceStore(this).file(path),detected.optString("encoding"))){char[] buffer=new char[8192];String tail="";int at=0,count;long deadline=android.os.SystemClock.elapsedRealtime()+10000;while((count=reader.read(buffer))!=-1){if(!alive)return;if(android.os.SystemClock.elapsedRealtime()>deadline)throw new IOException("Recherche interrompue après 10 secondes ; utiliser files_search_content pour un rapport borné");String part=tail+new String(buffer,0,count);int index=part.toLowerCase(Locale.ROOT).indexOf(needle.toLowerCase(Locale.ROOT));if(index>=0){int found=Math.max(0,at-tail.length()+index);runOnUiThread(()->{offset=Math.max(0,found-80);previous.clear();load();toast("Trouvé à la position "+found);});return;}tail=part.substring(Math.max(0,part.length()-needle.length()+1));at+=count;}}}else if(raw.toLowerCase(Locale.ROOT).contains(needle.toLowerCase(Locale.ROOT))){runOnUiThread(()->toast("Texte trouvé dans cette page"));return;}runOnUiThread(()->toast("Texte non trouvé dans la portée recherchée"));}catch(Exception ex){error(ex);}});}).setNegativeButton("Annuler",null).show();}
    private void edit(){if(editing)return;if(detected==null||!detected.optBoolean("editable")){toast("Édition disponible pour les textes Unicode jusqu’à 1 Mo");return;}WorkspaceCommands.IO.execute(()->{try{WorkspaceStore store=new WorkspaceStore(this);String before=WorkspaceTransfer.hash(store.file(path)),content=FileContent.full(this,path,1048576);if(!before.equals(WorkspaceTransfer.hash(store.file(path))))throw new IOException("Fichier modifié pendant l’ouverture");runOnUiThread(()->{if(!alive)return;sha=before;original=content;editing=true;body.removeAllViews();editor=new EditText(this);editor.setText(content);editor.setGravity(Gravity.TOP);editor.setTextColor(INK);editor.setTypeface(Typeface.MONOSPACE);body.addView(editor,new LinearLayout.LayoutParams(-1,-2));LinearLayout saves=new LinearLayout(this);body.addView(saves);button(saves,"Enregistrer une copie",()->save(false));button(saves,"Remplacer l’original",()->new AgentDialog.Builder(this).setTitle("Remplacer le fichier ?").setMessage("La version actuelle sera conservée dans la corbeille.").setPositiveButton("Remplacer",(d,n)->save(true)).setNegativeButton("Annuler",null).show());status.setText("Édition volontaire · copie recommandée · UTF-8");});}catch(Exception ex){error(ex);}});}
    private void save(boolean replace){if(editor==null)return;String value=editor.getText().toString();if(!replace){EditText name=new EditText(this);int dot=path.lastIndexOf('.');name.setText(dot>path.lastIndexOf('/')?path.substring(0,dot)+"-copie"+path.substring(dot):path+"-copie.txt");new AgentDialog.Builder(this).setTitle("Nouvelle copie UTF-8").setView(name).setPositiveButton("Enregistrer",(d,n)->write(name.getText().toString(),value,false)).setNegativeButton("Annuler",null).show();}else write(path,value,true);}
    private void write(String destination,String value,boolean replace){WorkspaceCommands.IO.execute(()->{try{WorkspaceStore s=new WorkspaceStore(this);JSONObject saved=replace?s.editText(path,value,sha):s.writeText(destination,value,false);runOnUiThread(()->{if(!alive)return;toast("Enregistré et vérifié par SHA-256");path=destination;editing=false;offset=0;previous.clear();load();});}catch(Exception ex){error(ex);}});}
    private void extract(){EditText target=new EditText(this);target.setText(path+"-extrait");new AgentDialog.Builder(this).setTitle("Nouveau dossier d’extraction").setView(target).setPositiveButton("Extraire",(d,n)->{String destination=target.getText().toString();WorkspaceCommands.IO.execute(()->{try{UniversalFiles.extract(this,path,destination,null,active());runOnUiThread(()->toast("Archive extraite et vérifiée : "+destination));}catch(Exception ex){error(ex);}});}).setNegativeButton("Annuler",null).show();}
    private void convert(){String[] formats=kind.equals("image")?new String[]{"png","jpg","webp"}:new String[]{"txt","pdf","docx","xlsx","csv","json","pptx"};new AgentDialog.Builder(this).setTitle("Créer une copie convertie").setItems(formats,(d,n)->{EditText target=new EditText(this);target.setText(path+"-converti."+formats[n]);new AgentDialog.Builder(this).setTitle("Nouvelle destination").setView(target).setPositiveButton("Convertir",(dialog,which)->{String destination=target.getText().toString();WorkspaceCommands.IO.execute(()->{try{UniversalFiles.convert(this,new JSONObject().put("path",path).put("destination",destination).put("format",formats[n]),active());runOnUiThread(()->toast("Copie convertie et vérifiée : "+destination));}catch(Exception ex){error(ex);}});}).setNegativeButton("Annuler",null).show();}).show();}
    private AgentClient.ResultCallback active(){return new AgentClient.ResultCallback(){public void finish(boolean ok,String value){}public boolean isActive(){return alive;}};}
    private void menu(){new AgentDialog.Builder(this).setTitle("Fichier").setItems(new String[]{"Informations","Aperçu hexadécimal","Ouvrir avec…","Partager","Convertir une copie","Ouvrir le projet dans Studio"},(d,n)->{if(n==0)WorkspaceCommands.IO.execute(()->{try{JSONObject info=FileFormats.detect(this,path).put("sha256",WorkspaceTransfer.hash(new WorkspaceStore(this).file(path)));runOnUiThread(()->new AgentDialog.Builder(this).setTitle("Informations").setMessage(info.toString()).setPositiveButton("Copier",(x,y)->copy(info.toString())).setNegativeButton("Fermer",null).show());}catch(Exception ex){error(ex);}});else if(n==1){hexMode=true;byteOffset=0;load();}else if(n==2||n==3)external(n==3);else if(n==4)convert();else if(n==5)startActivity(new Intent(this,VideoEditorActivity.class).putExtra("project_path",path));}).show();}
    private void external(boolean share){try{WorkspaceStore store=new WorkspaceStore(this);String mime=detected==null?store.mime(path):detected.optString("mime_type");Intent intent=new Intent(share?Intent.ACTION_SEND:Intent.ACTION_VIEW).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(share)intent.setType(mime).putExtra(Intent.EXTRA_STREAM,store.uri(path));else intent.setDataAndType(store.uri(path),mime);intent.setClipData(ClipData.newRawUri("Fichier",store.uri(path)));startActivity(Intent.createChooser(intent,share?"Partager":"Ouvrir avec…"));}catch(Exception ex){error(ex);}}
    private Bitmap pdfImage(File file,int at)throws Exception{try(ParcelFileDescriptor descriptor=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(descriptor);PdfRenderer.Page p=pdf.openPage(at)){float scale=Math.min(2,1600f/Math.max(p.getWidth(),p.getHeight()));Bitmap b=Bitmap.createBitmap(Math.max(1,Math.round(p.getWidth()*scale)),Math.max(1,Math.round(p.getHeight()*scale)),Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);return b;}}
    private Bitmap image(File file)throws Exception{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),options);if(options.outWidth<=0)return null;options.inJustDecodeBounds=false;options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>2048)options.inSampleSize*=2;return BitmapFactory.decodeFile(file.getPath(),options);}
    private String message(Exception ex){String value=ex.getMessage();return value==null?ex.getClass().getSimpleName():value;}
    private void error(Exception ex){runOnUiThread(()->{if(alive)toast(message(ex));});}
    private void toast(String value){if(alive)Toast.makeText(this,value,Toast.LENGTH_LONG).show();}
    private void acknowledge(){if(loaded&&hasWindowFocus())FileOpenRequests.visible(getIntent().getStringExtra("request_id"),path);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)acknowledge();}
    @Override public void onBackPressed(){if(editing&&editor!=null&&!original.equals(editor.getText().toString())){new AgentDialog.Builder(this).setTitle("Modifications non enregistrées").setPositiveButton("Enregistrer une copie",(d,n)->save(false)).setNegativeButton("Quitter sans enregistrer",(d,n)->finish()).setNeutralButton("Continuer l’édition",null).show();}else super.onBackPressed();}
    private void stopPlayer(){if(player!=null){player.release();player=null;}}
    @Override public void onPause(){if(player!=null)player.pause();super.onPause();}
    @Override public void onDestroy(){alive=false;generation++;if(body!=null)body.removeAllViews();stopPlayer();if(bitmap!=null)bitmap.recycle();super.onDestroy();}
}
